@use '../assets/styles/helpers/' as *;

.logo {
  display: inline-flex;
  align-items: center;
  column-gap: rem(10);
  padding-right: rem(15);
  border: rem(2) solid var(--color-dark);
  border-radius: rem(30);

  &__icon {
    @include square(50);
    @include flex-center;

    color: var(--color-light);
    background-color: var(--color-dark);
    border-radius: rem(30);

    & svg {
      width: rem(24);
      height: rem(43);
    }

    @include tablet-l {
      @include square(40);

      & svg {
        width: rem(15);
        height: rem(32);
      }
    }
  }

  &__text {
    @include fluid-text(24, 16);

    &--short {
      display: none;
    }

    @include tablet-l {
      &--full {
        display: none;
      }

      &--short {
        display: block;
      }
    }
  }
}
</style>